css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .52); display: flex; gap: 4%; }
.loader span { position: relative; flex: 1; overflow: hidden; border-radius: 5px; background: linear-gradient(#1e293b, #0b1220); box-shadow: inset 0 0 0 2px rgba(255, 255, 255, .08); perspective: 320px; }
.loader span::before { content: ''; position: absolute; z-index: 3; top: calc(50% - 1px); left: 0; width: 100%; height: 2px; background: rgba(0, 0, 0, .65); }
.loader span::after { content: ''; position: absolute; z-index: 2; top: 0; left: 0; width: 100%; height: 50%; border-radius: 5px 5px 0 0; transform-origin: bottom center; background: linear-gradient(var(--accent), var(--accent-2)); animation: flap calc(var(--loader-speed) * 1.2) cubic-bezier(.4, 0, .6, 1) infinite; }
.loader span:nth-child(2)::after { animation-delay: calc(var(--loader-speed) * .18); }
.loader span:nth-child(3)::after { animation-delay: calc(var(--loader-speed) * .36); }
@keyframes flap { 0% { transform: rotateX(0deg); } 42% { transform: rotateX(-90deg); } 58% { transform: rotateX(-90deg); } 59% { transform: rotateX(0deg); } 100% { transform: rotateX(0deg); } }
